'use strict';
const $=id=>document.getElementById(id),t=OrionI18n.t,denominators=[2,3,4,6,8,12],fractions=[[1,2],[2,3],[3,4],[1,3],[1,4],[5,6]];
let variant=OrionProgress.variant('fractions'),observedVariant=variant,observedTarget=OrionProgress.read().hashTarget;
let stage=0,denominator=4,selected=[],matches=[],solved=false,hintDepth=0,state='ready',saveFailed=false;
function target(v=variant,s=stage){return fractions[s===2?[0,3,4,0,3,4][v]:(v+s)%6];}
function count(){return selected.filter(Boolean).length;}
function solutions(){const [n,d]=target();return denominators.filter(x=>x!==d&&n*x%d===0).map(x=>[n*x/d,x]);}
function resetTrial(){denominator=4;selected=Array(4).fill(false);matches=[];solved=false;hintDepth=0;state='ready';saveFailed=false;$('notes').open=false;render();}
function resetMission(v=OrionProgress.variant('fractions')){variant=v;stage=0;resetTrial();}
function partition(d){if(solved||!denominators.includes(d))return;denominator=d;selected=Array(d).fill(false);state='partition';render();}
function toggle(i){if(solved||!Number.isInteger(i)||i<0||i>=denominator)return;selected[i]=!selected[i];state='ready';render();$('tile'+i).focus();}
function check(){if(solved)return;const [n,d]=target(),c=count();if(c*d!==n*denominator)state=c*d<n*denominator?'less':'more';else if(denominator===d)state='same';else if(matches.includes(denominator))state='duplicate';else {matches.push(denominator);state='match';if(stage<2||matches.length===2){solved=true;state='success';if(stage===2)saveFailed=!OrionProgress.earn('unity');}}render();if(solved&&stage<2)$('next').focus();}
function hints(){const [n,d]=target(),choices=solutions(),q=choices.find(x=>!matches.includes(x[1]))||choices[0];return[t('Compare the glowing area, not just the number of pieces. Both wholes are the same size.','比較發光面積，不只是碎片數量。兩個整體一樣大。'),t(`Use a division different from ${d}. Smaller pieces can join to cover the same area.`,`選擇不同於 ${d} 的等份數。較小碎片可以合起來，蓋住相同面積。`),t(`Try ${q[1]} equal parts and light ${q[0]}: ${q[0]}/${q[1]} = ${n}/${d}.`,`試分成 ${q[1]} 等份，點亮 ${q[0]} 份：${q[0]}/${q[1]} = ${n}/${d}。`)];}
function grid(el,d){el.style.gridTemplateColumns=`repeat(${d%2?d:d/2},minmax(0,1fr))`;el.style.gridTemplateRows=`repeat(${d%2?1:2},1fr)`;el.style.height='92px';}
function render(){const [n,d]=target(),complete=solved&&stage===2,progress=stage+Number(solved);window.OrionDiscovery?.update(complete);document.title=t('The Mosaic Treasury · Orion','碎片寶藏殿 · Orion');$('stageTitle').textContent=t(`Mosaic ${stage+1} · Set ${variant+1}`,`第 ${stage+1} 幅拼畫 · 第 ${variant+1} 組`);$('sceneStatus').textContent=t(`Mosaics restored · ${progress} / 3`,`已修復 ${progress} / 3 幅拼畫`);$('seals').textContent=Array.from({length:3},(_,i)=>i<progress?'◆':'◇').join(' ');$('scene').classList.toggle('complete',complete);
$('partition').innerHTML=denominators.map(x=>`<option value="${x}">${t(`${x} equal parts`,`${x} 等份`)}</option>`).join('');$('partition').value=denominator;$('partition').disabled=solved;
grid($('targetBoard'),d);$('targetBoard').innerHTML=Array.from({length:d},(_,i)=>`<span class="${i<n?'lit':''}"></span>`).join('');$('targetLabel').textContent=t(`Target: ${n}/${d} of the whole`,`目標：整體的 ${n}/${d}`);
grid($('board'),denominator);$('board').innerHTML=selected.map((on,i)=>`<button id="tile${i}" ${solved?'disabled':''} aria-pressed="${on}" aria-label="${t(`Tile ${i+1}, one of ${denominator} equal parts`,`碎片 ${i+1}，${denominator} 等份之一`)}">${on?'✦':'·'}</button>`).join('');selected.forEach((_,i)=>$('tile'+i).onclick=()=>toggle(i));$('amount').textContent=t(`Your area: ${count()}/${denominator}`,`你的面積：${count()}/${denominator}`);
$('goal').textContent=t(`Match ${n}/${d} using a different division. `,`用不同等份數拼出 ${n}/${d}。`)+(stage===2?t('Save TWO matches with different numbers of equal parts.','記錄兩種不同等份數的正確拼法。'):t('Save one matching mosaic.','記錄一幅相同面積的拼畫。'));$('reading').textContent=`${count()}/${denominator} ${count()*d===n*denominator?'=':count()*d<n*denominator?'<':'>'} ${n}/${d}`;$('reading').setAttribute('aria-label',t(`Your fraction ${count()}/${denominator} is ${count()*d===n*denominator?'equal to':count()*d<n*denominator?'less than':'greater than'} target ${n}/${d}`,`你的分數 ${count()}/${denominator} ${count()*d===n*denominator?'等於':count()*d<n*denominator?'小於':'大於'}目標 ${n}/${d}`));$('evidence').innerHTML=matches.map(x=>`<li>${n*x/d}/${x} = ${n}/${d} ✓</li>`).join('');
const messages={ready:t('Light some tiles, then test your mosaic.','點亮一些碎片，再測試拼畫。'),partition:t('A new blank division. Tap tiles to build your next mosaic.','已換成新的空白等份。點碎片來拼下一幅。'),less:t('Not enough glowing area yet. Add tiles or try a different division.','發光面積還不夠。增加碎片，或換另一等份數。'),more:t('Too much glowing area. Remove tiles or try a different division.','發光面積太多。移除碎片，或換另一等份數。'),same:t('The area matches! Now use a different number of equal parts to find another name for it.','面積相同！現在用不同等份數，找出它的另一個分數名稱。'),duplicate:t('This division is already recorded. Change the number of equal parts for a new match.','已記錄這種等份數。改變等份數，再找另一種拼法。'),match:t('One matching design saved! Change the division and make the same area again.','已記錄一種正確拼法！改變等份數，再拼出相同面積。'),success:t('The areas match. A mosaic seal glows!','面積相同，拼畫封印亮起來了！')};$('feedback').textContent=messages[state];$('check').hidden=solved;$('retry').hidden=solved;$('next').hidden=!solved||stage===2;$('reward').hidden=!complete;$('notes').hidden=!complete;$('hint').disabled=solved||hintDepth===3;$('hint').setAttribute('aria-label',t('Reveal the next clue','顯示下一個提示'));$('hint').setAttribute('aria-expanded',String(hintDepth>0));$('hints').hidden=!hintDepth;$('hints').innerHTML=hints().slice(0,hintDepth).map(h=>`<li>${h}</li>`).join('');$('retrySave').hidden=!saveFailed;$('saveStatus').textContent=saveFailed?t('Sigil earned, but saving failed. Try saving again.','已獲得符印，但儲存失敗。請再次儲存。'):OrionProgress.has('unity')?t('Unity Sigil saved in your collection.','合一符印已存入收藏。'):'';}
$('partition').onchange=()=>partition(Number($('partition').value));$('check').onclick=check;$('retry').onclick=()=>{if(!solved)resetTrial();};$('next').onclick=()=>{if(!solved||stage===2)return;stage++;resetTrial();$('partition').focus();};$('hint').onclick=()=>{hintDepth=Math.min(3,hintDepth+1);render();};$('replay').onclick=()=>{const v=OrionProgress.nextVariant('fractions',variant);observedVariant=OrionProgress.variant('fractions');resetMission(v);};$('retrySave').onclick=()=>{if(!solved||stage!==2)return;saveFailed=!OrionProgress.earn('unity');render();};
function syncProgress(){const v=OrionProgress.variant('fractions'),h=OrionProgress.read().hashTarget,changed=v!==observedVariant||h!==observedTarget;observedVariant=v;observedTarget=h;if(changed||solved&&stage===2&&!OrionProgress.has('unity')&&!saveFailed)resetMission();else render();}
window.addEventListener('orion-language',render);window.addEventListener('storage',e=>{if(e.key==='orion-expedition-progress-v1'||e.key===null)syncProgress();});window.addEventListener('pageshow',syncProgress);resetMission();OrionI18n.apply();
